fn create_passkey(hmac_secret: [REDACTED] -> Passkey {
    let builder = Passkey::mock("example.com".into());

    if let Some(hs) = hmac_secret {
        builder.hmac_secret(StoredHmacSecret {
            cred_with_uv: hs,
            cred_without_uv: None,
        })
    } else {
        builder
    }
    .build()
}

fn good_request() -> Request {
    Request {
        rp_id: "example.com".into(),
        client_data_hash: vec![0; 32].into(),
        allow_list: None,
        extensions: None,
        pin_auth: None,
        pin_protocol: None,
        options: Options {
            up: true,
            uv: true,
            rk: false,
        },
    }
}

